// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(address funder, uint256 amount) public {
        vm.assume(funder != address(0));
        amount = bound(amount, 1, 1 ether);

        vm.deal(funder, amount);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        uint256 before = c.balances(funder);
        vm.assume(before == amount);

        vm.prank(funder);
        bool ok;
        try c.withdraw{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.balances(funder) == 0);
        } else {
            assertTrue(c.balances(funder) == before);
        }
    }
}
